'use client';

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Textarea } from '@/components/ui/textarea';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Loader2, Sparkles, AlertCircle } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { createEstimate } from './actions';
import type { InitialEstimateOutput } from '@/ai/flows/generate-initial-estimate-from-prompt';

const formSchema = z.object({
  projectDescription: z
    .string()
    .min(50, {
      message: 'Please provide a more detailed description (at least 50 characters).',
    })
    .max(2000),
});

export default function EstimatePage() {
  const [isLoading, setIsLoading] = useState(false);
  const [estimate, setEstimate] = useState<InitialEstimateOutput | null>(null);
  const { toast } = useToast();

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      projectDescription: '',
    },
  });

  async function onSubmit(values: z.infer<typeof formSchema>) {
    setIsLoading(true);
    setEstimate(null);
    try {
      const result = await createEstimate(values);
      setEstimate(result);
    } catch (error) {
      toast({
        variant: 'destructive',
        title: 'An error occurred',
        description:
          'Failed to generate the estimate. Please try again later.',
      });
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="flex-1 space-y-4 p-4 md:p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h1 className="text-3xl font-bold tracking-tight font-headline">New Estimate</h1>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div>
          <Card>
            <CardHeader>
              <CardTitle>Project Details</CardTitle>
              <CardDescription>
                Describe your commercial renovation project. Be as detailed as possible for the best estimate.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Form {...form}>
                <form
                  onSubmit={form.handleSubmit(onSubmit)}
                  className="space-y-6"
                >
                  <FormField
                    control={form.control}
                    name="projectDescription"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Project Description</FormLabel>
                        <FormControl>
                          <Textarea
                            placeholder="e.g., We are planning a complete tenant fit-out for a 5,000 sq ft office space. This includes new open-plan work areas, 3 private offices, a conference room, and a kitchenette. We require modern finishes, glass partitions for offices, and updated network cabling throughout."
                            className="min-h-[200px]"
                            {...field}
                          />
                        </FormControl>
                        <FormDescription>
                          Include square footage, desired use (e.g., office, retail), scope of work, and desired quality of finishes.
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <Button type="submit" disabled={isLoading} className="w-full">
                    {isLoading ? (
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    ) : (
                      <Sparkles className="mr-2 h-4 w-4" />
                    )}
                    Generate Estimate
                  </Button>
                </form>
              </Form>
            </CardContent>
          </Card>
        </div>
        <div>
          <div className="space-y-8">
            {isLoading && (
              <Card>
                <CardHeader>
                  <CardTitle>Generating Your Estimate...</CardTitle>
                  <CardDescription>
                    Our AI is analyzing your project. Please wait a moment.
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-2 animate-pulse">
                     <div className="h-8 bg-muted rounded w-1/3"></div>
                     <div className="h-4 bg-muted rounded w-full"></div>
                     <div className="h-4 bg-muted rounded w-2/3"></div>
                  </div>
                   <div className="space-y-2 animate-pulse delay-150">
                     <div className="h-8 bg-muted rounded w-1/3"></div>
                     <div className="h-4 bg-muted rounded w-full"></div>
                     <div className="h-4 bg-muted rounded w-4/5"></div>
                  </div>
                </CardContent>
              </Card>
            )}
            {estimate ? (
              <>
                <Card className="bg-green-50 dark:bg-green-900/20 border-accent">
                  <CardHeader>
                    <CardTitle>Estimated Budget</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-5xl font-bold text-green-700 dark:text-green-400">
                      {estimate.estimatedBudget}
                    </p>
                  </CardContent>
                </Card>
                <Card>
                  <CardHeader>
                    <CardTitle>Assumptions</CardTitle>
                    <CardDescription>
                      The estimate is based on the following assumptions:
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <p className="text-muted-foreground whitespace-pre-wrap">{estimate.assumptions}</p>
                  </CardContent>
                </Card>
                <Card>
                  <CardHeader className="flex flex-row items-center gap-2">
                    <AlertCircle className="h-5 w-5 text-amber-500" />
                    <CardTitle>Disclaimer</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-sm text-muted-foreground">
                      {estimate.disclaimer}
                    </p>
                  </CardContent>
                </Card>
              </>
            ) : !isLoading && (
               <Card className="flex flex-col items-center justify-center text-center p-8 min-h-[400px]">
                  <CardHeader>
                    <Sparkles className="h-16 w-16 mx-auto text-muted-foreground/50" />
                    <CardTitle className="mt-4">Your AI-Powered Estimate</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-muted-foreground">
                      Your generated budget report will appear here.
                    </p>
                  </CardContent>
                </Card>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
